   Call(pet,"OfferFood");double initial=(double)Get(pet,"x");for(int i=0;i<160&&State(pet)!="Eat";i++)Step(pet,.02,far);Assert(State(pet)=="Eat","Did not reach bun");Assert(((System.Collections.ICollection)Get(pet,"tracks")).Count>0,"Walking tracks missing");Assert(Math.Abs((double)Get(pet,"x")-initial)>50,"Bun chase did not move");using(var frame=Frame(pet))frame.Save("feature-eating-preview.png");
