   foreach(string asset in new[]{"eating","stumble","leftStumble"}){var frames=(Bitmap[])Get(pet,asset);Assert(frames.Length==6,"Six animation frames missing: "+asset);foreach(var frame in frames)Assert(frame.Width>30&&frame.Height>30,"Empty generated animation frame");}
   var remaining=typeof(Usagi).GetMethod("FoodRemaining",BindingFlags.NonPublic|BindingFlags.Static);float last=1;for(double sample=0;sample<4.4;sample+=.02){float current=(float)remaining.Invoke(null,new object[]{sample});Assert(current<=last+.00001f&&current>=0,"Food consumption reversed");last=current;}Assert(last<.00001,"Final mouthful did not disappear");
   var bites=typeof(Usagi).GetMethod("FoodBites",BindingFlags.NonPublic|BindingFlags.Static);Assert((int)bites.Invoke(null,new object[]{.7})==0&&(int)bites.Invoke(null,new object[]{3.6})==4,"Bun bite sequence failed");for(int i=0;i<280;i++)Step(pet,.02,far);Assert(!(bool)Get(pet,"foodActive"),"Bun never finished");
