   Call(pet,"BeginTrip");Step(pet,.3,far);Assert(State(pet)=="Trip","Trip stage missing");using(var frame=Frame(pet))frame.Save("feature-trip-preview.png");
   using(var strip=new Bitmap(480*6,360))using(var g=Graphics.FromImage(strip)){int frameIndex=0;foreach(double stamp in new[]{.02,.2,.5,.3,.8,1.3}){Mood(pet,frameIndex<3?"Trip":"Recover");Set(pet,"stateTime",stamp);using(var frame=Frame(pet))g.DrawImageUnscaled(frame,frameIndex++*480,0);}strip.Save("stumble-detail-preview.png");}Mood(pet,"Trip");Set(pet,"stateTime",.3);
Step(pet,.45,far);Assert(State(pet)=="Recover","Recovery stage missing");Step(pet,1.4,far);Assert(State(pet)=="Walk","Trip did not resume walking");
