   Mood(pet,"Sleep");Set(pet,"speechTime",0.0);using(var sheet=new Bitmap(960,360))using(var g=Graphics.FromImage(sheet)){g.Clear(Color.FromArgb(17,24,37));g.FillRectangle(Brushes.Beige,480,0,480,360);Set(pet,"lightSleepInk",true);using(var frame=Frame(pet))g.DrawImageUnscaled(frame,0,0);Set(pet,"lightSleepInk",false);using(var frame=Frame(pet))g.DrawImageUnscaled(frame,480,0);sheet.Save("sleep-contrast-preview.png");}
