 static void Clones(){using(var pet=new Usagi()){
   ((PetSound)Get(pet,"sounds")).Enabled=false;var area=Screen.PrimaryScreen.WorkingArea;Set(pet,"x",area.Left+area.Width/2.0-pet.Width/2);Set(pet,"y",(double)area.Bottom-pet.Height+8);
   var list=(System.Collections.IList)typeof(Usagi).GetField("livePets",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);
   Call(pet,"RefreshCloneMenu");Assert(!((ContextMenuStrip)Get(pet,"menu")).Items.Contains((ToolStripItem)Get(pet,"cleanupMenu")),"Cleanup visible without clones");
   try{Call(pet,"DuplicatePets");for(int i=0;i<4;i++)pet.GetType().GetMethod("UpdateCloneQueue",flags).Invoke(pet,new object[]{.2});Assert(list.Count==4,"Expected four clones");Call(pet,"RefreshCloneMenu");Assert(((ContextMenuStrip)Get(pet,"menu")).Items.Contains((ToolStripItem)Get(pet,"cleanupMenu")),"Cleanup missing with clones");var sizes=new System.Collections.Generic.HashSet<float>();
     foreach(Usagi copy in list){((Timer)Get(copy,"timer")).Stop();((PetSound)Get(copy,"sounds")).Enabled=false;sizes.Add((float)Get(copy,"scale"));Assert(!(bool)Get(copy,"preferencesEnabled"),"Clone writes root settings");Assert(!((NotifyIcon)Get(copy,"tray")).Visible,"Clone made duplicate tray icon");
       double launch=(double)Get(copy,"x"),high=(double)Get(copy,"y");for(int j=0;j<65;j++){Step(copy,.02,new Point(area.Left,area.Top));high=Math.Min(high,(double)Get(copy,"y"));}Assert(high<area.Bottom-copy.Height-20,"Scatter did not rise");Assert(Math.Abs((double)Get(copy,"x")-launch)>20,"Scatter did not spread");Assert(!(bool)Get(copy,"scatterActive"),"Clone did not land");Assert(Math.Abs((double)Get(copy,"y")-(area.Bottom-copy.Height+8))<.1,"Clone landed outside taskbar");}
     Assert(sizes.Count==4,"Clone sizes are not varied");
     using(var scene=new Bitmap(960,420))using(var g=Graphics.FromImage(scene)){g.Clear(Color.FromArgb(255,248,226));g.DrawLine(Pens.BurlyWood,0,390,960,390);int n=0;foreach(Usagi copy in list){Set(copy,"x",(double)Get(pet,"x"));Set(copy,"y",(double)Get(pet,"y"));Set(copy,"scatterActive",true);Set(copy,"scatterVX",new[]{-225.0,140.0,-120.0,245.0}[n]);Set(copy,"scatterVY",-235.0-n%2*45);Set(copy,"speechTime",0.0);for(int j=0;j<25;j++)Step(copy,.02,new Point(area.Left,area.Top));using(var frame=Frame(copy))g.DrawImageUnscaled(frame,(int)((double)Get(copy,"x")-(double)Get(pet,"x"))+240,(int)((double)Get(copy,"y")-(double)Get(pet,"y"))+40);n++;}scene.Save("clone-scatter-preview.png");}

   }finally{Call(pet,"ClearClones");}Assert(list.Count==0,"Clone cleanup leaked pets");Call(pet,"RefreshCloneMenu");Assert(!((ContextMenuStrip)Get(pet,"menu")).Items.Contains((ToolStripItem)Get(pet,"cleanupMenu")),"Cleanup remained after last clone closed");using(var frame=Frame(pet))Assert(frame.Width>0,"Clone disposal broke shared root images");Console.WriteLine("PASS: four varied clones, scatter/landing, one tray icon, isolated settings and shared asset cleanup.");
 }}

 static bool SocialStep(object pet,double dt,Point cursor,bool moved){return (bool)pet.GetType().GetMethod("UpdateSocial",flags).Invoke(pet,new object[]{dt,cursor,moved});}
 static void SocialChecks(){using(var big=new Usagi())using(var small=new Usagi(true,big)){
   var list=(System.Collections.IList)typeof(Usagi).GetField("livePets",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);var area=Screen.PrimaryScreen.WorkingArea;var far=new Point(area.Left,area.Top);list.Add(big);list.Add(small);
   try{
     foreach(var pet in new[]{big,small}){((PetSound)Get(pet,"sounds")).Enabled=false;Set(pet,"x",area.Left+area.Width/2.0-pet.Width/2);Set(pet,"y",(double)area.Bottom-pet.Height+8);Set(pet,"idleTime",0.0);Set(pet,"greetCooldown",0.0);Set(pet,"socialBreak",0.0);Mood(pet,"Walk");}
     var rests=new System.Collections.Generic.HashSet<double>();for(int i=0;i<12;i++){big.GetType().GetMethod("Change",flags).Invoke(big,new object[]{Enum.Parse(big.GetType().GetField("mood",flags).FieldType,"Sit")});double duration=(double)Get(big,"restDuration");Assert(duration>=1.4&&duration<=4.5,"Rest duration outside natural range");rests.Add(duration);}Assert(rests.Count>8,"Rest duration is synchronized");Mood(big,"Walk");
     Set(big,"scale",1.3f);Set(small,"scale",.75f);Set(small,"x",(double)Get(big,"x")+70);Set(big,"direction",1);Set(small,"direction",-1);Set(big,"moving",true);
     Assert(SocialStep(big,.02,far,false),"Meeting did not start greeting");Assert((double)Get(big,"greetLeft")>0&&(double)Get(small,"greetLeft")>0,"Greeting was not mutual");double position=(double)Get(big,"x");SocialStep(big,.2,far,false);Assert((double)Get(big,"x")==position,"Greeting did not stop walking");SocialStep(small,.3,far,false);Assert((string)Get(small,"words")=="야하~!","Greeting reply missing");
     Call(big,"CancelSocial");Call(small,"CancelSocial");Set(big,"socialBreak",0.0);Set(small,"socialBreak",0.0);Mood(big,"Walk");Mood(small,"Walk");Set(big,"moving",true);Set(big,"speed",60.0);Set(small,"followCooldown",0.0);Set(small,"x",(double)Get(big,"x")-230);Assert(SocialStep(small,.02,far,false)&&(bool)Get(small,"following"),"Small pet did not follow larger leader");double before=(double)Get(small,"x");for(int i=0;i<40;i++)SocialStep(small,.02,far,false);Assert((double)Get(small,"x")>before+20,"Follower did not approach queue position");
     Call(small,"CancelSocial");Set(small,"socialBreak",0.0);Set(small,"playCooldown",0.0);Mood(small,"Walk");var cursor=new Point((int)(double)Get(small,"x")+small.Width/2+75,(int)(double)Get(small,"y")+small.Height-55);SocialStep(small,.02,cursor,true);Assert((double)Get(small,"playLeft")>0,"Cursor game did not start");before=(double)Get(small,"x");for(int i=0;i<35;i++)SocialStep(small,.02,cursor,false);Assert((double)Get(small,"x")>before,"Pet did not approach cursor");Set(small,"playLeft",1.0);before=(double)Get(small,"x");for(int i=0;i<45;i++)SocialStep(small,.02,cursor,false);Assert((double)Get(small,"x")<before,"Pet did not run away from cursor");
     Call(small,"CancelSocial");Set(small,"socialBreak",0.0);Set(small,"idleTime",10.0);Mood(big,"Sleep");Mood(small,"Drowsy");SocialStep(small,.02,far,false);Assert(Get(small,"napFriend")==big,"Pet did not gather beside sleeper");for(int i=0;i<330&&State(small)!="Sleep";i++)SocialStep(small,.02,far,false);Assert(State(small)=="Sleep","Gathering pet never slept");
     Mood(big,"Sleep");Mood(small,"Sleep");Set(big,"wakeDelay",-1.0);Set(small,"wakeDelay",-1.0);Set(small,"x",(double)Get(big,"x")+350);var wakeCursor=new Point((int)(double)Get(big,"x")+big.Width/2,(int)(double)Get(big,"y")+big.Height-55);foreach(var pet in new[]{big,small})pet.GetType().GetMethod("UpdateSleepWake",flags).Invoke(pet,new object[]{.016,wakeCursor,true});Assert(State(big)=="Sleep"&&State(small)=="Sleep","Group woke simultaneously on first mouse movement");Assert((double)Get(big,"wakeDelay")<(double)Get(small,"wakeDelay"),"Nearby pet does not wake first");for(int i=0;i<450;i++)foreach(var pet in new[]{big,small})pet.GetType().GetMethod("UpdateSleepWake",flags).Invoke(pet,new object[]{.016,wakeCursor,false});Assert(State(big)=="Stretch"&&State(small)=="Stretch","Staggered wake did not complete");Mood(small,"Sleep");small.GetType().GetMethod("BeginPointer",flags).Invoke(small,new object[]{wakeCursor});Assert(State(small)=="Stretch","Direct touch did not wake immediately");Set(small,"pointerDown",false);
     Mood(small,"Walk");Set(small,"idleTime",0.0);Set(small,"playLeft",2.0);Call(small,"OfferFood");Assert((double)Get(small,"playLeft")==0&&!(bool)Get(small,"following"),"Feeding did not cancel social behavior");
   }finally{list.Remove(small);list.Remove(big);}
   Console.WriteLine("PASS: mutual greeting/reply, size-ordered following, cursor approach/escape, shared nap gathering and feeding priority.");
 }}

 static void WrappingChecks(){
   var wrap=typeof(Usagi).GetMethod("WrapCenter",BindingFlags.NonPublic|BindingFlags.Static);
   Assert(Math.Abs((double)wrap.Invoke(null,new object[]{2025.0,0.0,1920.0,90.0})-(-75))<.001,"Right wrap lost overshoot");
   Assert(Math.Abs((double)wrap.Invoke(null,new object[]{-104.0,0.0,1920.0,90.0})-1996)<.001,"Left wrap lost overshoot");
   Assert(Math.Abs((double)wrap.Invoke(null,new object[]{105.0,-1920.0,0.0,90.0})-(-1995))<.001,"Negative monitor origin wrap failed");
   using(var pet=new Usagi()){((PetSound)Get(pet,"sounds")).Enabled=false;var area=Screen.PrimaryScreen.WorkingArea;var far=new Point(area.Left,area.Top);Set(pet,"lastCursor",far);Set(pet,"scale",1f);Set(pet,"idleTime",0.0);Set(pet,"x",area.Right+91.0-pet.Width/2);Set(pet,"y",(double)area.Bottom-pet.Height+8);Set(pet,"direction",1);Set(pet,"speed",64.0);Set(pet,"targetSpeed",64.0);Set(pet,"decisionTime",100.0);Set(pet,"autoHopIn",100.0);Set(pet,"tripCooldown",100.0);double stride=(double)Get(pet,"walkDistance");Step(pet,.02,far);Assert((double)Get(pet,"x")+pet.Width/2<area.Left,"Did not enter from opposite edge");Assert((int)Get(pet,"direction")==1&&(double)Get(pet,"speed")>60,"Wrap changed speed or direction");Assert((double)Get(pet,"walkDistance")-stride<3,"Teleport counted as a walking stride");
     Set(pet,"x",area.Right-10.0-pet.Width/2);using(var frame=Frame(pet))for(int yy=0;yy<frame.Height;yy++)for(int xx=0;xx<frame.Width;xx++)if((double)Get(pet,"x")+xx>=area.Right+1)Assert(frame.GetPixel(xx,yy).A==0,"Pet leaked beyond assigned monitor");
   }Console.WriteLine("PASS: left/right wrapping, negative monitor origin, continuous stride/speed and monitor clipping.");
 }

 static void MischiefChecks(){using(var root=new Usagi())using(var close=new Usagi(true,root))using(var other=new Usagi(true,root)){
   var list=(System.Collections.IList)typeof(Usagi).GetField("livePets",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);var drops=(System.Collections.IList)typeof(Usagi).GetField("foodDrops",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);var area=Screen.PrimaryScreen.WorkingArea;var cursor=new Point(area.Left,area.Top);foreach(var pet in new[]{root,close,other}){list.Add(pet);((PetSound)Get(pet,"sounds")).Enabled=false;Set(pet,"y",(double)area.Bottom-pet.Height+8);Set(pet,"x",area.Left+area.Width/2.0-pet.Width/2);Set(pet,"lastCursor",cursor);Set(pet,"decisionTime",100.0);Set(pet,"idleTime",0.0);Mood(pet,"Walk");}
   try{
     Set(close,"x",(double)Get(root,"x")+70);Set(other,"x",(double)Get(root,"x")+140);Call(root,"BeginTrip");Assert((double)Get(close,"scareDelay")>=0&&(double)Get(other,"scareDelay")>=0,"Neighbors did not notice stumble");foreach(var pet in new[]{close,other})pet.GetType().GetMethod("UpdateMischief",flags).Invoke(pet,new object[]{.4});Assert(State(close)=="Hop"&&State(other)=="Hop","Domino surprise did not hop");Assert((double)Get(close,"scareCooldown")>0,"Domino repeat guard missing");
     foreach(var pet in new[]{root,close,other}){Mood(pet,"Walk");Set(pet,"scatterActive",false);Set(pet,"pointerDown",false);Set(pet,"dragging",false);Set(pet,"scareDelay",-1.0);Set(pet,"hopHeight",0.0);}
     Set(root,"x",area.Left+area.Width/2.0-200-root.Width/2);Set(close,"x",area.Left+area.Width/2.0-60-close.Width/2);Set(other,"x",area.Left+area.Width/2.0+200-other.Width/2);Call(root,"OfferFood");Assert(drops.Count==1,"More than one shared bun spawned");Assert((bool)Get(root,"foodActive")&&(bool)Get(close,"foodActive")&&(bool)Get(other,"foodActive"),"Nearby pets did not join bun race");Step(close,.02,cursor);Assert(State(close)=="Eat"&&!(bool)Get(root,"foodActive")&&!(bool)Get(other,"foodActive"),"Bun was not awarded exclusively to first arrival");Call(close,"LeaveFoodRace");Assert(drops.Count==0,"Claimed bun persisted after cancellation");
     Call(root,"OfferFood");root.GetType().GetMethod("BeginPointer",flags).Invoke(root,new object[]{cursor});Assert(!(bool)Get(root,"foodActive")&&(bool)Get(close,"foodActive"),"Dragging one racer canceled others");foreach(var pet in new[]{root,close,other})Call(pet,"LeaveFoodRace");Assert(drops.Count==0,"Unclaimed bun leaked after all racers left");Set(root,"pointerDown",false);
     var held=typeof(Usagi).GetMethod("HeldFrame",BindingFlags.Static|BindingFlags.NonPublic);Assert((int)held.Invoke(null,new object[]{.3})!=(int)held.Invoke(null,new object[]{.5}),"Held pose does not wiggle");Assert((int)held.Invoke(null,new object[]{3.2})>=4,"Long hold has no pout pose");
     Set(root,"scale",1.4f);Set(root,"x",area.Left+area.Width/2.0-root.Width/2);Set(root,"speechTime",0.0);using(var sheet=new Bitmap(960,360))using(var g=Graphics.FromImage(sheet)){g.Clear(Color.FromArgb(255,248,226));for(int i=0;i<2;i++){Set(root,"foodActive",false);Mood(root,"Dragged");Set(root,"heldTime",i==0?.5:3.6);using(var frame=Frame(root))g.DrawImageUnscaled(frame,i*480,0);}sheet.Save("mischief-detail-preview.png");}
   }finally{foreach(var pet in new[]{root,close,other}){Call(pet,"LeaveFoodRace");list.Remove(pet);}}
   Console.WriteLine("PASS: domino surprise hops/cooldown, one shared bun and exclusive winner, race cancellation, generated wiggle/pout frames.");
 }}

